{"title": "Cortex XDR incidents - at a glance", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 2,
  "data": [
    {
      "name": "inc",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "incident"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.incident_id",
                    "size": 5000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.incident_id",
                            "data.cortex.incident_name",
                            "data.cortex.severity",
                            "data.cortex.status",
                            "data.cortex.is_resolved",
                            "data.cortex.assigned_user_pretty_name",
                            "data.cortex.alert_count",
                            "data.cortex.host_count",
                            "data.cortex.user_count",
                            "data.cortex.creation_time"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "(datum.c.is_resolved === 'true' || datum.c.is_resolved === true)",
          "as": "resolved"
        }
      ]
    },
    {
      "name": "incOpen",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.resolved"
        }
      ]
    },
    {
      "name": "incHigh",
      "source": "incOpen",
      "transform": [
        {
          "type": "filter",
          "expr": "indexof(['high','critical'], datum.c.severity) >= 0"
        }
      ]
    },
    {
      "name": "incUnassigned",
      "source": "incOpen",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.c.assigned_user_pretty_name"
        }
      ]
    },
    {
      "name": "incClosed",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.resolved"
        }
      ]
    },
    {
      "name": "al",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "alert"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "s": {
                  "filters": {
                    "filters": [
                      {
                        "match_all": {}
                      }
                    ]
                  },
                  "aggs": {
                    "a": {
                      "cardinality": {
                        "field": "data.cortex.alert_id"
                      }
                    },
                    "h": {
                      "cardinality": {
                        "field": "data.cortex.host_name"
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "%timefield%": "timestamp"
      },
      "format": {
        "property": "aggregations.scoped.s.buckets"
      }
    },
    {
      "name": "tiles",
      "values": [
        {
          "i": 0,
          "label": "Open incidents",
          "bad": false
        },
        {
          "i": 1,
          "label": "Open high / critical",
          "bad": true
        },
        {
          "i": 2,
          "label": "Unassigned open",
          "bad": true
        },
        {
          "i": 3,
          "label": "Closed incidents",
          "bad": false
        },
        {
          "i": 4,
          "label": "Alerts",
          "bad": false
        },
        {
          "i": 5,
          "label": "Hosts alerting",
          "bad": false
        }
      ],
      "transform": [
        {
          "type": "formula",
          "expr": "datum.i === 0 ? (length(data('incOpen'))) : datum.i === 1 ? (length(data('incHigh'))) : datum.i === 2 ? (length(data('incUnassigned'))) : datum.i === 3 ? (length(data('incClosed'))) : datum.i === 4 ? (length(data('al')) ? data('al')[0].a.value : 0) : datum.i === 5 ? (length(data('al')) ? data('al')[0].h.value : 0) : 0",
          "as": "value"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.46"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "max(14, min(height * 0.42, width / 6 * 0.26))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.bad && datum.value > 0 ? '#BD271E' : '#343741'"
          },
          "text": {
            "signal": "format(datum.value, ',')"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.82"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "field": "label"
          }
        }
      }
    }
  ]
}"}}

{"title": "Cortex XDR incidents - open by severity", "type": "vega", "aggs": [], "params": {"spec": "{
