    {
      "calculate": "indexof([\"critical\", \"high\", \"medium\", \"low\", \"informational\"], datum.c.severity) >= 0 ? datum.c.severity : 'other'",
      "as": "cat"
    },
    {
      "calculate": "1",
      "as": "n"
    },
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "n"
        }
