      "groupby": [
        "cat"
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "n",
          "as": "total"
        }
      ]
    },
    {
      "calculate": "datum.n / datum.total",
      "as": "pct"
    },
    {
      "calculate": "({\"critical\": \"#BD271E\", \"high\": \"#E7664C\", \"medium\": \"#D6BF57\", \"low\": \"#54B399\", \"informational\": \"#98A2B3\", \"other\": \"#D3DAE6\"})[datum.cat] || '#D3DAE6'",
