        },
        "stroke": "#fff",
        "strokeWidth": 1.5,
        "cornerRadius": 2
      },
      "encoding": {
        "theta": {
          "field": "n",
          "type": "quantitative",
          "stack": true
        },
        "order": {
          "field": "n",
          "sort": "descending"
        },
        "color": {
          "field": "cat_key",
          "type": "nominal",
          "title": null,
          "legend": {
            "orient": "right",
            "labelLimit": 180,
            "symbolType": "circle",
            "labelExpr": "slice(datum.label, 3)"
          },
          "scale": {
            "range": {
              "field": "cat_hex"
            }
          }
        },
        "tooltip": [
          {
            "field": "cat",
            "title": "Value"
          },
          {
            "field": "n",
            "title": "Count"
          },
          {
            "field": "pct",
            "title": "Share",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "radius": {
          "expr": "min(width, height) * 0.36"
        },
        "fontSize": 11,
        "fontWeight": "bold",
        "fill": "#fff"
      },
      "encoding": {
        "theta": {
          "field": "n",
          "type": "quantitative",
          "stack": true
        },
        "order": {
          "field": "n",
          "sort": "descending"
        },
        "text": {
          "condition": {
            "test": "datum.pct >= 0.06",
            "field": "n",
            "type": "quantitative"
          },
          "value": ""
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "sum",
              "field": "n",
              "as": "t"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 26,
        "fontWeight": "bold",
        "fill": "#343741",
        "dy": -7
      },
      "encoding": {
        "text": {
          "field": "t",
          "type": "quantitative",
          "format": ","
        },
        "x": {
          "value": {
            "expr": "width / 2"
          }
        },
        "y": {
          "value": {
            "expr": "height / 2"
          }
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "k"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 11,
        "fill": "#69707D",
        "dy": 13,
        "text": "open incidents"
      },
      "encoding": {
        "x": {
          "value": {
            "expr": "width / 2"
          }
        },
        "y": {
          "value": {
            "expr": "height / 2"
          }
        }
      }
    }
  ],
  "view": {
    "stroke": null
  }
}"}}

